mapper.select:
SELECT t.id, t.course_id, t.user_id, u.real_name as user_name, u.avatar as user_avatar, t.title, t.content, t.is_pinned, t.is_closed, t.view_count, t.reply_count, t.last_reply_time, t.create_time, t.update_time FROM mg_course_thread t LEFT JOIN sys_user u ON t.user_id = u.id AND u.is_deleted = 0
t.is_deleted = 0
AND t.course_id = #{courseId}
AND t.user_id = #{userId}
AND t.title LIKE CONCAT('%', #{title}, '%')
AND t.is_pinned = #{pinned}
AND t.is_closed = #{closed}
ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}
ORDER BY t.is_pinned DESC, t.last_reply_time DESC, t.create_time DESC
